<script lang="ts">
  import { untrack } from 'svelte';import { page } from '$app/state';import { goto } from '$app/navigation';
  import { adminRequest } from '$lib/admin/client';import { emptySelection, toggleRow, togglePage } from '$lib/admin/selection';import type { SelectionPreview } from '$lib/admin/types';import ConfirmDialog from '$lib/components/admin/ConfirmDialog.svelte';
  let userId=$derived(page.params.id!);let detail=$state<any>(null),rows=$state<any[]>([]),total=$state(0),busy=$state(false),problem=$state(''),notice=$state('');
  let search=$state(''),mode=$state('all'),level=$state('all'),category=$state(''),from=$state(''),to=$state(''),sort=$state('completed_at'),direction=$state('desc'),currentPage=$state(1),pageSize=$state(20);
  let selection=$state(emptySelection()),preview=$state<SelectionPreview|null>(null),modal=$state<'delete'|'reset'|'account'|null>(null),accountStep=$state(1),typedEmail=$state(''),password=$state(''),expanded=$state(''),operationId=$state('');let sequence=0;
  let allPage=$derived(rows.length>0&&rows.every(row=>selection.ids.includes(row.id)));let somePage=$derived(rows.some(row=>selection.ids.includes(row.id))&&!allPage);
  const filter=()=>Object.fromEntries(Object.entries({search,mode,level,category,from,to,sort,direction,page:currentPage,pageSize}).filter(([,value])=>value!==''));
  async function load(reset=false,clear=true){if(reset)currentPage=1;if(clear)selection=emptySelection();const request=++sequence;busy=true;problem='';try{const [u,history]=await Promise.all([adminRequest(`api/users/${userId}`),adminRequest(`api/users/${userId}/attempts?${new URLSearchParams(Object.entries(filter()).map(([k,v])=>[k,String(v)]))}`)]);if(request!==sequence)return;detail=u;rows=history.items;total=history.total;}catch(e){if(request===sequence)problem=(e as Error).message;}finally{if(request===sequence)busy=false;}}
  $effect(()=>{userId;untrack(()=>{load(true);});return()=>{sequence++;};});
  $effect(()=>{search;mode;level;category;from;to;sort;direction;selection=emptySelection();});
  async function rowToggle(id:string){problem='';if(selection.selectionId&&selection.ids.includes(id)){busy=true;try{const p=await adminRequest<SelectionPreview>(`api/users/${userId}/selections/${selection.selectionId}/exclude`,{ids:[id]});selection={ids:p.ids,selectionId:p.selectionId};}catch(e){problem=(e as Error).message;selection=emptySelection();}finally{busy=false;}}else selection=toggleRow(selection,id);}
  async function selectMatching(){busy=true;problem='';try{const p=await adminRequest<SelectionPreview>(`api/users/${userId}/selections`,{kind:'matching',filter:filter()});selection={ids:p.ids,selectionId:p.selectionId};}catch(e){problem=(e as Error).message;}finally{busy=false;}}
  async function begin(action:'delete'|'reset'|'account',ids?:string[]){if(busy)return;busy=true;problem='';notice='';preview=null;operationId=crypto.randomUUID();try{if(action==='delete'){preview=selection.selectionId&&!ids?await adminRequest(`api/users/${userId}/selections/${selection.selectionId}`):await adminRequest(`api/users/${userId}/selections`,{kind:'ids',ids:ids??selection.ids});}else if(action==='reset')preview=await adminRequest(`api/users/${userId}/reset`,{action:'preview'});accountStep=1;typedEmail='';password='';modal=action;}catch(e){problem=(e as Error).message;selection=emptySelection();}finally{busy=false;}}
  async function execute(){busy=true;problem='';try{let result;if(modal==='account'){await adminRequest('reauth',{password});password='';result=await adminRequest(`api/users/${userId}/delete-account`,{operationId,typedEmail});}else{result=await adminRequest(`api/users/${userId}/${modal==='reset'?'reset':'delete-attempts'}`,{action:'execute',selectionId:preview?.selectionId,operationId});}modal=null;selection=emptySelection();if(result.status==='complete'){await goto('/admin/users');return;}notice=result.status==='succeeded'?'Changes saved. Performance and review progress were recalculated.':`Account deletion status: ${result.status}. See Audit for the operation and retry.`;await load(false);}catch(e){password='';problem=(e as Error).message;modal=null;selection=emptySelection();}finally{busy=false;}}
</script>
<a href="/admin/users" class="muted">← Users</a><h1>{detail?.displayName||'User details'}</h1>
{#if problem}<p role="alert" class="error">{problem}</p>{/if}{#if notice}<p role="status" class="success">{notice}</p>{/if}
{#if detail}
<section class="admin-card"><h2>{detail.email}</h2><p class="muted">Account ID: {userId} · {detail.protectedAdmin?'Protected administrator':detail.status}</p><div class="stats"><div><strong>{detail.performance?.examCount??detail.examCount??0}</strong>Saved exams</div><div><strong>{detail.performance?.bestPercentage??0}%</strong>High score</div><div><strong>{detail.performance?.averagePercentage??0}%</strong>Average</div></div><p class="muted">Performance includes all remaining exams, regardless of the filters below.</p>{#if detail.state?.progressCoverage==='partial'}<p class="muted">Some older exams have no answer snapshots. Their scores remain in the summary; per-question progress is incomplete.</p>{/if}{#if detail.performance?.categories?.length}<details><summary>Category performance</summary><ul>{#each detail.performance.categories as c}<li>{c.category}: {c.totalCorrect}/{c.totalQuestions} ({c.percentage}%)</li>{/each}</ul></details>{/if}</section>
{/if}
<section class="admin-card"><h2>Exam history</h2><form class="toolbar" onsubmit={e=>{e.preventDefault();load(true);}}>
<label>Category / exam ID <input bind:value={search} maxlength="200"/></label><label>Mode <select bind:value={mode}><option value="all">All modes</option><option value="practice">Practice</option><option value="mock">Mock</option></select></label><label>Level <select bind:value={level}><option value="all">All levels</option><option value="professional">Professional</option><option value="subprofessional">Subprofessional</option></select></label><label>Category <input bind:value={category}/></label><label>From (UTC) <input type="date" bind:value={from}/></label><label>Through (UTC) <input type="date" bind:value={to}/></label><label>Sort <select bind:value={sort}><option value="completed_at">Date</option><option value="percentage">Score</option><option value="category">Category</option></select></label><label>Order <select bind:value={direction}><option value="desc">Descending</option><option value="asc">Ascending</option></select></label><button class="btn-primary" disabled={busy}>Apply filters</button><button class="btn-ghost" type="button" disabled={busy} onclick={()=>{search='';mode='all';level='all';category='';from='';to='';load(true);}}>Clear filters</button><button class="btn-ghost" type="button" disabled={busy} onclick={()=>load()}>Refresh</button>
</form>
<div class="toolbar" aria-live="polite"><span>{selection.ids.length} selected · {total} matching exams</span><button class="btn-ghost" disabled={!selection.ids.length||busy} onclick={()=>selection=emptySelection()}>Clear selection</button>{#if allPage&&total>rows.length&&!selection.selectionId}<button class="btn-ghost" onclick={selectMatching} disabled={busy}>Select all {total} matching exams</button>{/if}<button class="danger" disabled={!selection.ids.length||busy||detail?.protectedAdmin||detail?.status!=='active'} onclick={()=>begin('delete')}>Delete selected</button></div>
<div class="table-scroll" aria-busy={busy}><table><thead><tr><th><label class="check-label"><input type="checkbox" checked={allPage} indeterminate={somePage} disabled={busy||!rows.length||detail?.protectedAdmin} onchange={()=>selection=togglePage(selection,rows.map(r=>r.id))}/><span>Select page</span></label></th><th>Exam</th><th>Completed</th><th>Score</th><th>Actions</th></tr></thead><tbody>{#each rows as row(row.id)}<tr><td><label class="check-label"><input type="checkbox" checked={selection.ids.includes(row.id)} disabled={busy||detail?.protectedAdmin} onchange={()=>rowToggle(row.id)}/><span class="muted">Select</span></label></td><td>{row.category||'Mixed Categories'}<br/><small>{row.mode} · {row.level||'Legacy'}<br/>{row.id}</small></td><td>{new Date(row.completed_at).toLocaleString()}</td><td>{row.score}/{row.total} ({row.total>0?Math.round(row.score/row.total*100):0}%)</td><td><div class="toolbar"><button class="btn-ghost" onclick={()=>expanded=expanded===row.id?'':row.id}>{expanded===row.id?'Hide':'Review'}</button><button class="danger" disabled={busy||detail?.protectedAdmin||detail?.status!=='active'} onclick={()=>begin('delete',[row.id])}>Delete</button></div></td></tr>{#if expanded===row.id}<tr><td colspan="5">{#if row.questions?.length}{#each row.questions as q,i}<div class="snapshot"><p>{i+1}. {q.question}</p><p class="muted">Answer: {row.user_answers?.[i]??'Unanswered'} · Correct: {q.correct_answer}</p>{#if q.explanation}<p>{q.explanation}</p>{/if}</div>{/each}{:else}<p>No question snapshot was saved for this legacy exam.</p>{/if}</td></tr>{/if}{:else}<tr><td colspan="5">{busy?'Loading exams…':'No exams match these filters.'}</td></tr>{/each}</tbody></table></div>
<div class="pagination"><button class="btn-ghost" disabled={currentPage<=1||busy} onclick={()=>{currentPage--;load(false,false);}}>Previous</button><span>Page {currentPage} of {Math.max(1,Math.ceil(total/pageSize))}</span><button class="btn-ghost" disabled={currentPage*pageSize>=total||busy} onclick={()=>{currentPage++;load(false,false);}}>Next</button><label>Rows <select bind:value={pageSize} onchange={()=>load(true)}><option value={20}>20</option><option value={50}>50</option></select></label></div></section>
{#if detail}<section class="admin-card"><h2>Account actions</h2><p class="muted">Reset removes all saved exams, paused sessions, and learning progress while keeping the account. Account deletion removes the account too.</p><div class="toolbar"><button class="danger" disabled={busy||detail.protectedAdmin||detail.status!=='active'} onclick={()=>begin('reset')}>Reset progress</button><button class="danger" disabled={busy||detail.protectedAdmin||detail.status!=='active'} onclick={()=>begin('account')}>Delete account</button></div>{#if detail.protectedAdmin}<p>Administrator accounts are protected from these actions.</p>{/if}</section>{/if}
{#if modal}<ConfirmDialog title={modal==='account'?'Delete account':modal==='reset'?'Reset all progress':'Delete selected exams'} {busy} onClose={()=>modal=null}>
<p>Target: <strong>{detail?.email}</strong></p>
{#if modal==='account'}{#if accountStep===1}<p>This permanently removes the account and all saved exams, paused sessions, and learning progress. It cannot be undone.</p><div class="toolbar"><button class="btn-ghost" onclick={()=>modal=null}>Cancel</button><button class="danger" onclick={()=>accountStep=2}>Continue to final confirmation</button></div>{:else}<form onsubmit={e=>{e.preventDefault();execute();}}><label>Type the user's email <input bind:value={typedEmail} autocomplete="off" required/></label><label>Your administrator password <input type="password" bind:value={password} autocomplete="current-password" required/></label><div class="toolbar"><button class="btn-ghost" type="button" disabled={busy} onclick={()=>modal=null}>Cancel</button><button class="danger" disabled={busy||typedEmail!==detail?.email||!password}>{busy?'Deleting…':'Permanently delete account'}</button></div></form>{/if}
{:else}<p>{modal==='reset'?`Remove all ${preview?.count??0} saved exams, paused sessions, and learning progress? The account stays active.`:`Permanently delete exactly ${preview?.count??0} selected exams? Performance and learning progress will be recalculated from the remaining exams.`}</p><div class="toolbar"><button class="btn-ghost" disabled={busy} onclick={()=>modal=null}>Cancel</button><button class="danger" disabled={busy} onclick={execute}>{busy?'Saving…':'Confirm deletion'}</button></div>{/if}
</ConfirmDialog>{/if}
<style>.snapshot{padding:1rem 0;border-bottom:1px solid #3a2b4a;white-space:pre-wrap}details{margin-top:1rem}summary{cursor:pointer}dialog input{display:block;width:100%;margin:.5rem 0 1rem}</style>
